import { describe, expect, it } from 'vitest';
import { createHash } from 'node:crypto';
import { InstancedMesh, Matrix4 } from 'three';
import { createGameConfig } from '../../src/core/Configuration';
import { createWorld } from '../../src/world/World';
import { BiomeDecorationView } from '../../src/engine/BiomeDecorationView';
import { ChunkManager } from '../../src/world/ChunkManager';

describe('biome decoration compatibility with the previous release', () => {
  it('exactly preserves the former instance transforms and colours, including the 2200 cap', () => {
    // Generated by the previous implementation before its selected-record cache was removed.
    const cases = [
      { config: createGameConfig(), count: 1429, hash: '961aef4ef9183fcf2c22189fd09d624b1008518ac03bded6ab3fe0d8b71d04cb' },
      { config: createGameConfig({ world: { seed: 123, sizeMeters: 80, resolution: 32, obstacleCount: 10 } }), count: 227, hash: '248d280a8a852276b4299e0be24ec5e993039601aab784548b8e1cc0832246e4' },
      { config: createGameConfig({ world: { sizeMeters: 2000, resolution: 8, heightScale: 0, rimHeight: 0, obstacleCount: 0 }, controls: { playAreaRadius: 150 } }), count: 2200, hash: '1b069554fa8efa0e9ff1d289917a65def97171770c15b64b9b753e8812c356b2' },
    ];
    for (const { config, count, hash } of cases) {
      const world = createWorld(config), view = new BiomeDecorationView(world, 64), chunks = new ChunkManager(world, 64);
      view.load(chunks.update(0, 0, 3000).loaded);
      const rows = (view.group.children as InstancedMesh[]).flatMap(mesh => Array.from({ length: mesh.count }, (_, i) => {
        const m = new Matrix4(); mesh.getMatrixAt(i, m);
        return JSON.stringify([mesh.name.split(':').at(-1), m.elements, [...mesh.instanceColor!.array.slice(i * 3, i * 3 + 3)]]);
      })).sort();
      expect(rows).toHaveLength(count);
      expect(createHash('sha256').update(JSON.stringify(rows)).digest('hex')).toBe(hash);
      view.dispose();
    }
  }, 30000);
});
